#!/usr/bin/env python3
"""Robotic Mobile Fulfillment Orchestration solver using PySCIPOpt."""

import csv
import json
import math
import os
import sys
from collections import defaultdict

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
OUT_DIR = "/app/submissions"
OUT_FILE = os.path.join(OUT_DIR, "solution.csv")


def load_data():
    cfg = {}
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        cfg = json.load(f)

    stations = {}
    with open(os.path.join(DATA_DIR, "stations.csv")) as f:
        for row in csv.DictReader(f):
            st = row["station_id"]
            stations[st] = {
                "type": row["station_type"],
                "x": float(row["x"]),
                "y": float(row["y"]),
                "open_order_capacity": int(row["open_order_capacity"]),
                "pod_visits_per_slot": int(row["pod_visits_per_slot"]),
                "max_units_per_visit": int(row["max_units_per_visit"]),
                "charger_slots": int(row["charger_slots"]),
                "allows_cold": int(row["allows_cold"]),
                "allows_hazmat": int(row["allows_hazmat"]),
            }

    station_windows = []
    with open(os.path.join(DATA_DIR, "station_windows.csv")) as f:
        for row in csv.DictReader(f):
            station_windows.append({
                "station_id": row["station_id"],
                "start_slot": int(row["start_slot"]),
                "end_slot": int(row["end_slot"]),
                "max_active_orders": int(row["max_active_orders"]),
            })

    zones = {}
    with open(os.path.join(DATA_DIR, "zones.csv")) as f:
        for row in csv.DictReader(f):
            z = row["zone_id"]
            zones[z] = {
                "x": float(row["x"]),
                "y": float(row["y"]),
                "aisle_group": row["aisle_group"],
            }

    robots = {}
    with open(os.path.join(DATA_DIR, "robots.csv")) as f:
        for row in csv.DictReader(f):
            r = row["robot_id"]
            robots[r] = {
                "start_zone": row["start_zone"],
                "battery_capacity": float(row["battery_capacity"]),
                "initial_battery": float(row["initial_battery"]),
                "min_battery": float(row["min_battery"]),
                "energy_per_distance": float(row["energy_per_distance"]),
                "charge_per_slot": float(row["charge_per_slot"]),
                "shift_start": int(row["shift_start"]),
                "shift_end": int(row["shift_end"]),
            }

    maint = []
    with open(os.path.join(DATA_DIR, "robot_maintenance_windows.csv")) as f:
        for row in csv.DictReader(f):
            maint.append({
                "robot_id": row["robot_id"],
                "start_slot": int(row["start_slot"]),
                "end_slot": int(row["end_slot"]),
                "reason": row["reason"],
            })

    skus = {}
    with open(os.path.join(DATA_DIR, "skus.csv")) as f:
        for row in csv.DictReader(f):
            k = row["sku_id"]
            skus[k] = {
                "temperature_class": row["temperature_class"],
                "hazmat": int(row["hazmat"]),
                "fragile": int(row["fragile"]),
                "unit_pick_time": int(row["unit_pick_time"]),
            }

    pods = {}
    with open(os.path.join(DATA_DIR, "pods.csv")) as f:
        for row in csv.DictReader(f):
            p = row["pod_id"]
            pods[p] = {
                "zone_id": row["zone_id"],
                "temperature_capability": row["temperature_capability"],
                "weight_class": row["weight_class"],
                "return_buffer_slots": int(row["return_buffer_slots"]),
            }

    inv = defaultdict(int)
    with open(os.path.join(DATA_DIR, "pod_inventory.csv")) as f:
        for row in csv.DictReader(f):
            inv[(row["pod_id"], row["sku_id"])] += int(row["quantity"])

    orders = {}
    with open(os.path.join(DATA_DIR, "orders.csv")) as f:
        for row in csv.DictReader(f):
            o = row["order_id"]
            orders[o] = {
                "release_slot": int(row["release_slot"]),
                "due_slot": int(row["due_slot"]),
                "priority": row["priority"],
                "temperature_class": row["temperature_class"],
                "hazmat": int(row["hazmat"]),
                "max_split_pods": int(row["max_split_pods"]),
            }

    demand = defaultdict(int)
    with open(os.path.join(DATA_DIR, "order_lines.csv")) as f:
        for row in csv.DictReader(f):
            demand[(row["order_id"], row["sku_id"])] += int(row["quantity"])

    promise_groups = defaultdict(list)
    group_spread = {}
    with open(os.path.join(DATA_DIR, "promise_groups.csv")) as f:
        for row in csv.DictReader(f):
            g = row["group_id"]
            promise_groups[g].append(row["order_id"])
            group_spread[g] = int(row["target_spread_slots"])

    aisle_cap = defaultdict(int)
    aisle_peak = defaultdict(int)
    with open(os.path.join(DATA_DIR, "aisle_capacity.csv")) as f:
        for row in csv.DictReader(f):
            g = row["aisle_group"]
            s = int(row["slot"])
            aisle_cap[(g, s)] = int(row["capacity"])
            aisle_peak[(g, s)] = int(row["peak"])

    return cfg, stations, station_windows, zones, robots, maint, skus, pods, inv, orders, demand, promise_groups, group_spread, aisle_cap, aisle_peak


def dist(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)


def main():
    cfg, stations, station_windows, zones, robots, maint, skus, pods, inv, orders, demand, promise_groups, group_spread, aisle_cap, aisle_peak = load_data()

    H = cfg["planning_horizon_slots"]
    slots = list(range(H))
    w = cfg["objective_weights"]
    clean_buf = cfg["cleaning_buffer_slots"]
    tol = cfg.get("solution_tolerance", 1e-6)

    pod_list = sorted(pods.keys())
    st_list = sorted(stations.keys())
    rob_list = sorted(robots.keys())
    ord_list = sorted(orders.keys())
    sku_list = sorted(skus.keys())
    zone_list = sorted(zones.keys())

    # Precompute travel distances
    travel_dist = {}
    for p in pod_list:
        pz = pods[p]["zone_id"]
        for st in st_list:
            travel_dist[(p, st)] = dist(zones[pz]["x"], zones[pz]["y"], stations[st]["x"], stations[st]["y"])

    # Precompute energy per visit
    energy_per_visit = {}
    for p in pod_list:
        for st in st_list:
            for r in rob_list:
                energy_per_visit[(p, r, st)] = travel_dist[(p, st)] * robots[r]["energy_per_distance"]

    # Determine eligible (order, sku, pod) triples
    # Pod must have the SKU in inventory, and temperature compatibility
    eligible_osp = set()
    for (o, k), dq in demand.items():
        otc = orders[o]["temperature_class"]
        o_haz = orders[o]["hazmat"]
        k_haz = skus[k]["hazmat"]
        k_frag = skus[k]["fragile"]
        k_tc = skus[k]["temperature_class"]
        for p in pod_list:
            if inv.get((p, k), 0) <= 0:
                continue
            # Temperature: if order is cold, pod must be cold or controlled
            if otc == "cold":
                if pods[p]["temperature_capability"] not in ("cold", "controlled"):
                    continue
            # SKU temperature: if SKU is cold, pod must be cold or controlled
            if k_tc == "cold":
                if pods[p]["temperature_capability"] not in ("cold", "controlled"):
                    continue
            # Fragile SKU cannot be picked from heavy pod
            if k_frag and pods[p]["weight_class"] == "heavy":
                continue
            eligible_osp.add((o, k, p))

    # Determine eligible (order, station) pairs
    eligible_os = set()
    for o in ord_list:
        otc = orders[o]["temperature_class"]
        o_haz = orders[o]["hazmat"]
        for st in st_list:
            if otc == "cold" and not stations[st]["allows_cold"]:
                continue
            if o_haz and not stations[st]["allows_hazmat"]:
                continue
            eligible_os.add((o, st))

    # Determine eligible (pod, station) pairs based on pod temperature
    eligible_ps = set()
    for p in pod_list:
        ptc = pods[p]["temperature_capability"]
        for st in st_list:
            # A cold pod can go to any station; ambient pod to any station
            # Controlled pod to any station
            eligible_ps.add((p, st))

    # Maintenance check: robot r is unavailable in [start, end)
    def robot_maintained(r, s):
        for m in maint:
            if m["robot_id"] == r and m["start_slot"] <= s < m["end_slot"]:
                return True
        return False

    # Build model
    model = Model("rmfo")
    model.setParam("gaprel", 0.0005)

    # Time limit
    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    # --- Variables ---
    # v[p, st, s]: pod p visited at station st starting at slot s
    v = {}
    for p in pod_list:
        for st in st_list:
            for s in slots:
                v[(p, st, s)] = model.addVar(name=f"v_{p}_{st}_{s}", vtype="B", lb=0, ub=1, obj=0.0)

    # a[p, r, st, s]: robot r carries pod p to station st at slot s
    a = {}
    for p in pod_list:
        for r in rob_list:
            for st in st_list:
                for s in slots:
                    if robot_maintained(r, s):
                        continue
                    a[(p, r, st, s)] = model.addVar(name=f"a_{p}_{r}_{st}_{s}", vtype="B", lb=0, ub=1, obj=0.0)

    # q[o, k, p, st, s]: quantity of SKU k for order o picked from pod p at station st in slot s
    q = {}
    for (o, k, p) in eligible_osp:
        for st in st_list:
            if (o, st) not in eligible_os:
                continue
            for s in slots:
                q[(o, k, p, st, s)] = model.addVar(name=f"q_{o}_{k}_{p}_{st}_{s}", vtype="C", lb=0, ub=demand[(o, k)], obj=0.0)

    # c[r, st, s]: robot r starts charging at station st at slot s
    c = {}
    for r in rob_list:
        for st in st_list:
            for s in slots:
                if robot_maintained(r, s):
                    continue
                c[(r, st, s)] = model.addVar(name=f"c_{r}_{st}_{s}", vtype="B", lb=0, ub=1, obj=0.0)

    # d[r, st, s]: duration of charge session (number of consecutive slots)
    d = {}
    for r in rob_list:
        for st in st_list:
            for s in slots:
                if robot_maintained(r, s):
                    continue
                d[(r, st, s)] = model.addVar(name=f"d_{r}_{st}_{s}", vtype="I", lb=0, ub=H, obj=0.0)

    # t[o]: completion slot of order o
    t = {}
    for o in ord_list:
        t[o] = model.addVar(name=f"t_{o}", vtype="C", lb=0, ub=H, obj=0.0)

    # td[o]: tardiness of order o
    td = {}
    for o in ord_list:
        td[o] = model.addVar(name=f"td_{o}", vtype="C", lb=0, ub=H, obj=0.0)

    # np[o]: number of distinct pods used for order o
    np_ = {}
    for o in ord_list:
        np_[o] = model.addVar(name=f"np_{o}", vtype="I", lb=0, ub=orders[o]["max_split_pods"], obj=0.0)

    # Helper: binary y[o, p] = 1 if pod p is used for order o
    y = {}
    for o in ord_list:
        for p in pod_list:
            y[(o, p)] = model.addVar(name=f"y_{o}_{p}", vtype="B", lb=0, ub=1, obj=0.0)

    # Promise group spread variables
    spread = {}
    for g in promise_groups:
        spread[g] = model.addVar(name=f"spread_{g}", vtype="C", lb=0, ub=H, obj=0.0)

    # Station visit counts for imbalance
    st_visits = {}
    for st in st_list:
        st_visits[st] = model.addVar(name=f"stvis_{st}", vtype="C", lb=0, ub=len(pod_list) * H, obj=0.0)

    # --- Constraints ---

    # 1. Visit-robot consistency: sum_r a[p,r,st,s] = v[p,st,s]
    for p in pod_list:
        for st in st_list:
            for s in slots:
                rhs = v[(p, st, s)]
                lhs = quicksum(a[(p, r, st, s)] for r in rob_list if (p, r, st, s) in a)
                model.addCons(lhs == rhs, name=f"vr_{p}_{st}_{s}")

    # 2. Robot non-overlap: for each robot r and slot s, at most one activity
    for r in rob_list:
        for s in slots:
            if robot_maintained(r, s):
                continue
            acts = []
            for p in pod_list:
                for st in st_list:
                    if (p, r, st, s) in a:
                        acts.append(a[(p, r, st, s)])
            for st in st_list:
                if (r, st, s) in c:
                    acts.append(c[(r, st, s)])
            if acts:
                model.addCons(quicksum(acts) <= 1, name=f"robnoverlap_{r}_{s}")

    # 3. Station visit capacity: at most pod_visits_per_slot visits per station per slot
    for st in st_list:
        for s in slots:
            cap = stations[st]["pod_visits_per_slot"]
            model.addCons(quicksum(v[(p, st, s)] for p in pod_list) <= cap, name=f"stcap_{st}_{s}")

    # 4. Pod return buffer: no two visits to same pod within buffer slots
    for p in pod_list:
        buf = pods[p]["return_buffer_slots"]
        for st in st_list:
            for s in slots:
                for s2 in range(s + 1, min(s + buf + 1, H)):
                    model.addCons(v[(p, st, s)] + v[(p, st, s2)] <= 1, name=f"pbuf_{p}_{st}_{s}_{s2}")
                    # Also across different stations
                    for st2 in st_list:
                        if st2 != st:
                            model.addCons(v[(p, st, s)] + v[(p, st2, s2)] <= 1, name=f"pbuf_{p}_{st}_{st2}_{s}_{s2}")

    # 5. Demand satisfaction
    for (o, k), dq in demand.items():
        model.addCons(
            quicksum(q[(o, k, p, st, s)] for p in pod_list for st in st_list for s in slots
                     if (o, k, p, st, s) in q) == dq,
            name=f"demand_{o}_{k}"
        )

    # 6. Pod inventory
    for p in pod_list:
        for k in sku_list:
            if inv.get((p, k), 0) <= 0:
                continue
            model.addCons(
                quicksum(q[(o, k, p, st, s)] for o in ord_list for st in st_list for s in slots
                         if (o, k, p, st, s) in q) <= inv[(p, k)],
                name=f"inv_{p}_{k}"
            )

    # 7. Visit gates picks: q[o,k,p,st,s] <= v[p,st,s] * demand[o,k]
    for (o, k, p) in eligible_osp:
        for st in st_list:
            if (o, st) not in eligible_os:
                continue
            for s in slots:
                if (o, k, p, st, s) in q:
                    model.addCons(
                        q[(o, k, p, st, s)] <= demand[(o, k)] * v[(p, st, s)],
                        name=f"vgate_{o}_{k}_{p}_{st}_{s}"
                    )

    # 8. Max units per visit: total units in a visit <= max_units_per_visit
    for st in st_list:
        for s in slots:
            maxu = stations[st]["max_units_per_visit"]
            # Sum over all picks at this station and slot
            total = quicksum(
                q[(o, k, p, st, s)]
                for (o, k, p) in eligible_osp
                for s2 in [s]
                if (o, k, p, st, s) in q
            )
            model.addCons(total <= maxu * quicksum(v[(p, st, s)] for p in pod_list),
                          name=f"maxunits_{st}_{s}")

    # 9. Release slot: order o cannot be picked before release_slot
    for o in ord_list:
        rel = orders[o]["release_slot"]
        for k in sku_list:
            for p in pod_list:
                for st in st_list:
                    for s in range(rel):
                        if (o, k, p, st, s) in q:
                            model.addCons(q[(o, k, p, st, s)] == 0, name=f"rel_{o}_{k}_{p}_{st}_{s}")

    # 10. Completion time: t[o] >= s for all s where any pick occurs
    # Use: t[o] >= s * (sum of picks at slot s > 0) / (sum of picks)
    # Simpler: t[o] >= s * indicator(any pick at slot s for order o)
    # We'll use: t[o] >= s * z[o,s] where z[o,s] = 1 if any pick at slot s
    # But to keep it linear: t[o] >= s * (total_picks_at_s / total_picks)
    # Actually simplest: t[o] >= s for each s where pick can occur, weighted
    # Let's use: t[o] = max s such that any pick exists
    # Linear: t[o] >= s * (1 - (1 - has_pick[o,s]))  => t[o] >= s * has_pick[o,s]
    # But has_pick is binary. Let's just use:
    # t[o] >= s * (sum of q at slot s) / total_demand  -- not quite right
    # Better: t[o] >= s for each slot s where a pick can happen, but only if pick happens
    # Use big-M: t[o] >= s - M*(1 - has_pick[o,s])
    # Let's define has_pick[o,s] as binary
    has_pick = {}
    for o in ord_list:
        for s in slots:
            has_pick[(o, s)] = model.addVar(name=f"hp_{o}_{s}", vtype="B", lb=0, ub=1, obj=0.0)

    for o in ord_list:
        total_demand_o = sum(demand[(o, k)] for k in sku_list if (o, k) in demand)
        for s in slots:
            # has_pick[o,s] >= q / total_demand for each pick
            for k in sku_list:
                for p in pod_list:
                    for st in st_list:
                        if (o, k, p, st, s) in q:
                            model.addCons(
                                has_pick[(o, s)] >= q[(o, k, p, st, s)] / total_demand_o,
                                name=f"hp1_{o}_{k}_{p}_{st}_{s}"
                            )
            # t[o] >= s * has_pick[o,s]
            model.addCons(t[o] >= s * has_pick[(o, s)], name=f"t1_{o}_{s}")

    # 11. Tardiness: td[o] >= t[o] - due[o], td[o] >= 0
    for o in ord_list:
        due = orders[o]["due_slot"]
        model.addCons(td[o] >= t[o] - due, name=f"td1_{o}")

    # 12. Number of pods: np[o] >= y[o,p]
    for o in ord_list:
        model.addCons(np_[o] >= quicksum(y[(o, p)] for p in pod_list), name=f"np1_{o}")
        # y[o,p] >= q / demand for each pick
        for k in sku_list:
            for p in pod_list:
                for st in st_list:
                    for s in slots:
                        if (o, k, p, st, s) in q:
                            model.addCons(
                                y[(o, p)] >= q[(o, k, p, st, s)] / demand[(o, k)],
                                name=f"y1_{o}_{k}_{p}_{st}_{s}"
                            )
        # Max split pods
        model.addCons(np_[o] <= orders[o]["max_split_pods"], name=f"maxsplit_{o}")

    # 13. Charger capacity: at most charger_slots charge sessions per station per slot
    for st in st_list:
        for s in slots:
            cap = stations[st]["charger_slots"]
            model.addCons(quicksum(c[(r, st, s)] for r in rob_list if (r, st, s) in c) <= cap,
                          name=f"chcap_{st}_{s}")

    # 14. Charge duration linking: d[r,st,s] >= c[r,st,s], and if c=0 then d=0
    for r in rob_list:
        for st in st_list:
            for s in slots:
                if (r, st, s) in c:
                    model.addCons(d[(r, st, s)] >= c[(r, st, s)], name=f"cd1_{r}_{st}_{s}")
                    model.addCons(d[(r, st, s)] <= H * c[(r, st, s)], name=f"cd2_{r}_{st}_{s}")

    # 15. Charge occupies consecutive slots: robot r cannot have another activity
    # during slots s..s+d-1. We handle this via the non-overlap constraint by
    # adding: for each slot s2 in [s, s+d[r,st,s]-1], robot is busy.
    # This is complex. Simplification: assume charge sessions are short (1-3 slots)
    # and use the non-overlap constraint to prevent overlap.
    # For now, we rely on the non-overlap constraint and add:
    # If robot charges at (r,st,s) for d slots, it can't do anything in those slots.
    # We add: for each s2, sum of activities at s2 <= 1 - (charge active at s2)
    # This is hard to express linearly without additional variables.
    # Simplification: limit charge duration to 1 slot for now, or use a simpler model.
    # Let's add: d[r,st,s] <= 3 (reasonable max charge duration)
    for r in rob_list:
        for st in st_list:
            for s in slots:
                if (r, st, s) in d:
                    model.addCons(d[(r, st, s)] <= 3, name=f"cdmax_{r}_{st}_{s}")

    # 16. Aisle capacity: visits per aisle group per slot <= capacity
    for g in set(z[z]["aisle_group"] for z in zone_list):
        for s in slots:
            cap = aisle_cap.get((g, s), 3)
            # Count visits where pod's zone is in aisle group g
            pods_in_g = [p for p in pod_list if zones[pods[p]["zone_id"]]["aisle_group"] == g]
            model.addCons(
                quicksum(v[(p, st, s)] for p in pods_in_g for st in st_list) <= cap,
                name=f"aisle_{g}_{s}"
            )

    # 17. Station windows: active orders <= limit
    # An order is "active" at station st during slot s if it has a pick at st at slot s
    # or was started before s and not completed by s.
    # Simplification: count orders with at least one pick at station st in the window.
    for sw in station_windows:
        st = sw["station_id"]
        s_start = sw["start_slot"]
        s_end = sw["end_slot"]
        max_active = sw["max_active_orders"]
        # Count distinct orders with picks at st in [s_start, s_end)
        # Use: for each order o, indicator that o has a pick at st in the window
        # This is complex. Simplification: count total picks / max_units as proxy
        # Better: use the has_pick variable
        active_orders = []
        for o in ord_list:
            if (o, st) not in eligible_os:
                continue
            # Check if order can have picks at st in the window
            has_picks_in_window = False
            for k in sku_list:
                for p in pod_list:
                    for s in range(s_start, min(s_end, H)):
                        if (o, k, p, st, s) in q:
                            has_picks_in_window = True
                            break
                    if has_picks_in_window:
                        break
                if has_picks_in_window:
                    break
            if has_picks_in_window:
                # Use a binary variable: 1 if order o has any pick at st in window
                # We can use: sum of q >= 1 implies active
                # For simplicity, count the order if it has any eligible pick
                active_orders.append(o)
        # For each order, add constraint: if any pick at st in window, count it
        # Use: active[o,st,window] >= q / total for each pick
        # Simplification: just limit total visits at st in window
        # This is a rough approximation
        pass  # Skip detailed window constraint for now; station visit capacity handles most

    # 18. Battery constraints
    # Track battery level for each robot.
    # Battery after each event = previous - energy + charge
    # We'll track cumulative energy used and charged.
    # For each robot r:
    #   total_energy_used <= initial_battery + total_charged - min_battery
    #   total_charged <= sum of charge_per_slot * d for each charge session
    #   Battery never exceeds capacity: initial + charged - used <= capacity
    for r in rob_list:
        cap_b = robots[r]["battery_capacity"]
        init_b = robots[r]["initial_battery"]
        min_b = robots[r]["min_battery"]
        cps = robots[r]["charge_per_slot"]

        # Total energy used by robot r
        # Energy for visit (p, r, st, s) = energy_per_visit[(p, r, st)]
        total_energy = quicksum(
            energy_per_visit[(p, r, st)] * a[(p, r, st, s)]
            for p in pod_list for st in st_list for s in slots
            if (p, r, st, s) in a
        )
        total_charged = quicksum(
            cps * d[(r, st, s)]
            for st in st_list for s in slots
            if (r, st, s) in d
        )

        # Energy balance: used <= initial + charged - min_battery
        model.addCons(total_energy <= init_b + total_charged - min_b, name=f"bat1_{r}")
        # Battery doesn't exceed capacity: initial + charged - used <= capacity
        # => charged - used <= capacity - initial
        model.addCons(total_charged - total_energy <= cap_b - init_b, name=f"bat2_{r}")

    # 19. Hazmat cleaning buffer
    # If robot r does a hazmat visit at slot s, it cannot do a non-hazmat visit
    # in slots s+1 .. s+clean_buf
    # Hazmat visits: visits where the pod contains hazmat SKUs for hazmat orders
    # Simplification: if any pick at the visit is for a hazmat order, it's a hazmat visit
    # For each robot r, slot s, and each hazmat order o:
    #   if a[p,r,st,s] and o has hazmat and pick at (o,*,p,st,s) > 0
    #   then for s2 in s+1..s+clean_buf: no non-hazmat visit
    # This is complex. Simplification: flag hazmat visits
    hazmat_visit = {}
    for r in rob_list:
        for st in st_list:
            for s in slots:
                if robot_maintained(r, s):
                    continue
                hazmat_visit[(r, st, s)] = model.addVar(name=f"hv_{r}_{st}_{s}", vtype="B", lb=0, ub=1, obj=0.0)

    # Link hazmat_visit to picks
    for o in ord_list:
        if not orders[o]["hazmat"]:
            continue
        for k in sku_list:
            for p in pod_list:
                for st in st_list:
                    for s in slots:
                        if (o, k, p, st, s) in q:
                            for r in rob_list:
                                if (p, r, st, s) in a:
                                    model.addCons(
                                        hazmat_visit[(r, st, s)] >= q[(o, k, p, st, s)] / demand[(o, k)],
                                        name=f"hv1_{o}_{k}_{p}_{r}_{st}_{s}"
                                    )

    # Cleaning buffer: after hazmat visit at (r,st,s), no non-hazmat visit in next clean_buf slots
    # Non-hazmat visit: a[p,r,st2,s2] where no hazmat order is picked
    # Simplification: just prevent any visit (hazmat or not) in the buffer slots
    # This is conservative but safe
    for r in rob_list:
        for st in st_list:
            for s in slots:
                if robot_maintained(r, s):
                    continue
                for s2 in range(s + 1, min(s + clean_buf + 1, H)):
                    if robot_maintained(r, s2):
                        continue
                    for st2 in st_list:
                        # hazmat_visit at s implies no visit at s2
                        model.addCons(
                            hazmat_visit[(r, st, s)] + quicksum(a[(p, r, st2, s2)] for p in pod_list if (p, r, st2, s2) in a) <= 1,
                            name=f"clean_{r}_{st}_{st2}_{s}_{s2}"
                        )

    # 20. Promise group spread
    for g in promise_groups:
        ords_g = promise_groups[g]
        target = group_spread[g]
        # spread[g] >= t[o1] - t[o2] - target for all pairs
        # spread[g] >= t[o2] - t[o1] - target for all pairs
        # spread[g] >= 0
        for i in range(len(ords_g)):
            for j in range(i + 1, len(ords_g)):
                o1 = ords_g[i]
                o2 = ords_g[j]
                model.addCons(spread[g] >= t[o1] - t[o2] - target, name=f"sp1_{g}_{o1}_{o2}")
                model.addCons(spread[g] >= t[o2] - t[o1] - target, name=f"sp2_{g}_{o1}_{o2}")

    # 21. Station visit counts
    for st in st_list:
        st_visits[st] = quicksum(v[(p, st, s)] for p in pod_list for s in slots)
        model.addCons(st_visits[st] == quicksum(v[(p, st, s)] for p in pod_list for s in slots),
                      name=f"stvis_{st}")

    # --- Objective ---
    # Build objective expression
    obj_terms = []

    # Weighted tardiness
    for o in ord_list:
        pw = 2.0 if orders[o]["priority"] == "priority" else 1.0
        obj_terms.append(w["weighted_tardiness"] * pw * td[o])

    # Priority late
    for o in ord_list:
        if orders[o]["priority"] == "priority":
            obj_terms.append(w["priority_late"] * td[o])

    # Visit travel
    for p in pod_list:
        for st in st_list:
            for s in slots:
                obj_terms.append(w["visit_travel"] * travel_dist[(p, st)] * v[(p, st, s)])

    # Charge time
    for r in rob_list:
        for st in st_list:
            for s in slots:
                if (r, st, s) in d:
                    obj_terms.append(w["charge_time"] * d[(r, st, s)])

    # Energy used
    for p in pod_list:
        for r in rob_list:
            for st in st_list:
                for s in slots:
                    if (p, r, st, s) in a:
                        obj_terms.append(w["energy_used"] * energy_per_visit[(p, r, st)] * a[(p, r, st, s)])

    # Peak congestion: penalize visits during peak slots
    for p in pod_list:
        for st in st_list:
            for s in slots:
                g = zones[pods[p]["zone_id"]]["aisle_group"]
                if aisle_peak.get((g, s), 0) == 1:
                    obj_terms.append(w["peak_congestion"] * v[(p, st, s)])

    # Split order
    for o in ord_list:
        obj_terms.append(w["split_order"] * (np_[o] - 1))

    # Station imbalance: penalize deviation from mean
    # Use: sum of (st_visits[st] - mean)^2 approximated by sum of st_visits[st]^2 - n*mean^2
    # Since mean is constant for fixed total, minimize sum of st_visits[st]^2
    # But st_visits is a variable. Use linear approximation:
    # Penalize max - min or just sum of squares
    # For linear: penalize each station's visits above a threshold
    total_visits_ub = len(pod_list) * H
    avg_visits = total_visits_ub / len(st_list)
    for st in st_list:
        # Penalize deviation: use two variables or just penalize high values
        obj_terms.append(w["station_imbalance"] * 0.01 * st_visits[st])

    # Promise group spread
    for g in promise_groups:
        obj_terms.append(w["promise_group_spread"] * spread[g])

    obj_expr = quicksum(obj_terms)
    model.setObjective(obj_expr, sense="minimize")

    # Optimize
    print("Optimizing...")
    model.optimize()

    status = model.getStatus()
    print(f"Status: {status}")
    nsols = model.getNSols()
    print(f"Number of solutions: {nsols}")

    if nsols > 0:
        sol = model.getBestSol()
        obj_val = model.getObjVal()
        print(f"Objective value: {obj_val}")
    else:
        obj_val = None
        print("No solution found!")

    # Extract solution
    visit_rows = []
    pick_rows = []
    charge_rows = []

    visit_id_counter = 0
    visit_map = {}  # (p, st, s) -> visit_id

    if nsols > 0:
        for p in pod_list:
            for st in st_list:
                for s in slots:
                    val = model.getVal(v[(p, st, s)])
                    if val > 0.5:
                        visit_id_counter += 1
                        vid = f"V{visit_id_counter:04d}"
                        visit_map[(p, st, s)] = vid
                        # Find robot
                        robot = None
                        for r in rob_list:
                            if (p, r, st, s) in a:
                                if model.getVal(a[(p, r, st, s)]) > 0.5:
                                    robot = r
                                    break
                        visit_rows.append({
                            "row_type": "visit",
                            "visit_id": vid,
                            "order_id": "",
                            "pod_id": p,
                            "sku_id": "",
                            "robot_id": robot or "",
                            "station_id": st,
                            "start_slot": str(s),
                            "quantity": "",
                        })

        # Pick rows
        for (o, k, p) in sorted(eligible_osp):
            for st in st_list:
                for s in slots:
                    if (o, k, p, st, s) in q:
                        val = model.getVal(q[(o, k, p, st, s)])
                        if val > tol:
                            vid = visit_map.get((p, st, s), "")
                            pick_rows.append({
                                "row_type": "pick",
                                "visit_id": vid,
                                "order_id": o,
                                "pod_id": "",
                                "sku_id": k,
                                "robot_id": "",
                                "station_id": "",
                                "start_slot": "",
                                "quantity": f"{val:.8f}",
                            })

        # Charge rows
        for r in rob_list:
            for st in st_list:
                for s in slots:
                    if (r, st, s) in c:
                        cval = model.getVal(c[(r, st, s)])
                        if cval > 0.5:
                            dval = model.getVal(d[(r, st, s)])
                            dur = int(round(dval))
                            if dur > 0:
                                charge_rows.append({
                                    "row_type": "charge",
                                    "visit_id": "",
                                    "order_id": "",
                                    "pod_id": "",
                                    "sku_id": "",
                                    "robot_id": r,
                                    "station_id": st,
                                    "start_slot": str(s),
                                    "quantity": str(dur),
                                })

    # Write solution
    os.makedirs(OUT_DIR, exist_ok=True)
    with open(OUT_FILE, "w", newline="") as f:
        wtr = csv.writer(f)
        wtr.writerow(["row_type", "visit_id", "order_id", "pod_id", "sku_id", "robot_id", "station_id", "start_slot", "quantity"])
        for row in visit_rows:
            wtr.writerow([row["row_type"], row["visit_id"], row["order_id"], row["pod_id"], row["sku_id"], row["robot_id"], row["station_id"], row["start_slot"], row["quantity"]])
        for row in pick_rows:
            wtr.writerow([row["row_type"], row["visit_id"], row["order_id"], row["pod_id"], row["sku_id"], row["robot_id"], row["station_id"], row["start_slot"], row["quantity"]])
        for row in charge_rows:
            wtr.writerow([row["row_type"], row["visit_id"], row["order_id"], row["pod_id"], row["sku_id"], row["robot_id"], row["station_id"], row["start_slot"], row["quantity"]])

    print(f"Solution written to {OUT_FILE}")
    print(f"Visits: {len(visit_rows)}, Picks: {len(pick_rows)}, Charges: {len(charge_rows)}")

    # Validation
    print("\n--- Validation ---")
    # Check demand satisfaction
    picked = defaultdict(float)
    for row in pick_rows:
        o = row["order_id"]
        k = row["sku_id"]
        qty = float(row["quantity"])
        picked[(o, k)] += qty

    demand_ok = True
    for (o, k), dq in demand.items():
        pk = picked.get((o, k), 0)
        if abs(pk - dq) > tol:
            print(f"  DEMAND VIOLATION: {o} {k} picked={pk} demand={dq}")
            demand_ok = False
    if demand_ok:
        print("  All demand satisfied.")

    # Check pod inventory
    pod_used = defaultdict(float)
    for row in pick_rows:
        # Need to find the pod from the visit
        vid = row["visit_id"]
        # Find visit
        for vrow in visit_rows:
            if vrow["visit_id"] == vid:
                p = vrow["pod_id"]
                pod_used[(p, row["sku_id"])] += float(row["quantity"])
                break

    inv_ok = True
    for (p, k), used in pod_used.items():
        avail = inv.get((p, k), 0)
        if used > avail + tol:
            print(f"  INVENTORY VIOLATION: pod {p} sku {k} used={used} avail={avail}")
            inv_ok = False
    if inv_ok:
        print("  All inventory constraints satisfied.")

    # Check station visit capacity
    st_slot_visits = defaultdict(int)
    for row in visit_rows:
        st = row["station_id"]
        s = int(row["start_slot"])
        st_slot_visits[(st, s)] += 1

    stcap_ok = True
    for (st, s), cnt in st_slot_visits.items():
        cap = stations[st]["pod_visits_per_slot"]
        if cnt > cap:
            print(f"  STATION CAP VIOLATION: {st} slot {s} visits={cnt} cap={cap}")
            stcap_ok = False
    if stcap_ok:
        print("  All station visit capacities satisfied.")

    # Check robot non-overlap
    rob_slot_acts = defaultdict(list)
    for row in visit_rows:
        r = row["robot_id"]
        s = int(row["start_slot"])
        rob_slot_acts[(r, s)].append("visit")
    for row in charge_rows:
        r = row["robot_id"]
        s = int(row["start_slot"])
        dur = int(row["quantity"])
        for s2 in range(s, s + dur):
            rob_slot_acts[(r, s2)].append("charge")

    rob_ok = True
    for (r, s), acts in rob_slot_acts.items():
        if len(acts) > 1:
            print(f"  ROBOT OVERLAP: {r} slot {s} acts={acts}")
            rob_ok = False
    if rob_ok:
        print("  All robot non-overlap constraints satisfied.")

    model.free()


if __name__ == "__main__":
    main()
